class Solution:
    def minSteps(self, s: str, t: str) -> int:
        cs = [0] * 26
        ct = [0] * 26
        for ch in s:
            cs[ord(ch) - 97] += 1
        for ch in t:
            ct[ord(ch) - 97] += 1
        return sum(abs(cs[i] - ct[i]) for i in range(26))

