from collections import Counter


class Solution:
    def minSteps(self, s: str, t: str) -> int:
        cnt = Counter(s)
        keep = 0
        for ch in t:
            if cnt[ch] > 0:
                cnt[ch] -= 1
                keep += 1
        return len(s) + len(t) - 2 * keep

