var minSteps = function(s, t) {
    const cnt = new Array(26).fill(0);
    for (const ch of s) cnt[ch.charCodeAt(0) - 97]++;
    let keep = 0;
    for (const ch of t) {
        const i = ch.charCodeAt(0) - 97;
        if (cnt[i] > 0) {
            cnt[i]--;
            keep++;
        }
    }
    return s.length + t.length - 2 * keep;
};
